chrome.runtime.onInstalled.addListener(()=>{chrome.contextMenus.create({id:"trg-block-element",title:"Thêm vào bộ lọc...",contexts:["all"],documentUrlPatterns:["<all_urls>"]})});chrome.runtime.onMessage.addListener((n,e,s)=>{});chrome.contextMenus.onClicked.addListener((n,e)=>{n.menuItemId==="trg-block-element"&&(e!=null&&e.id)&&chrome.tabs.sendMessage(e.id,{type:"CONTEXT_BLOCK_REQUEST"})});
